********** BEGIN CONTEXT **********

```latex
\section{Preliminaries} \label{sec:prelim}

Let $\cM_d$ denote the set of $d\times d$ matrices with complex entries. Consider a quantum system described by the $d$-dimensional Hilbert space $\C^d$. Quantum states of the system are described by the set of \emph{density operators} given by $\cbr{\rho\in\cM_d:\rho\geq0,\Tr(\rho)=1}$. Pure state density operators are rank-one projectors $\rho=\ketbra{\psi}$. A density operator $\zeta$ on $\C^{d_A}\otimes\C^{d_B}$ is called \emph{separable} if it can be written as $\zeta = \sum_{i\in I} p_i\, \rho_i \otimes \sigma_i \enspace$ for some finite set $I$, a probability distribution $p:I\rightarrow [0,1]$, and density operators $\{\rho_i:i\in I\}$ on $\C^{d_A}$ and $\{\sigma_i:i\in I\}$ on $\C^{d_B}$. We denote by $\mathrm{Sep(A:B)}$ the set of all separable state on $\C^{d_A}\otimes\C^{d_B}$ with respect to the bi-partition $A:B$, where the two subsystems are labeled $A$ and $B$.

\textbf{Representation of Quantum channels.} A \emph{quantum channel} is a completely positive and trace-preserving linear map $\cT:\cM_{d_A}\rightarrow\cM_{d_B}$. We denote by $\cI_d: \cM_d \rightarrow \cM_d$ the identity channel, i.e., the identity map on $\cM_d$. Let $\cT:\cM_{d_A}\rightarrow\cM_{d_B}$ be a quantum channel. Let
\begin{equation}\label{eq:def_ChoiMatrix}
    C_\cT=\textstyle\sum_{i,j\in[d]} \cT\br{\ketbratwo{i}{j}}\otimes \ketbratwo{i}{j} \enspace,
\end{equation}
where $\cbr{\ket{i}:i\in [d_A]}$ is the standard basis of $\C^{d_A}$. The operator $C_\cT$ is called the \emph{Choi matrix} of $\cT$.
For any quantum channel $\cT$, there exists a finite set $I$ and linear operators $K_i:\C^{d_A}\rightarrow \C^{d_B}$ for any $i\in I$ such that $\sum_{i\in I} K_i^\dagger K_i=\id_{d_A}$ and $\cT(X)=\sum_{i\in I} K_i X K_i^\dagger$, for all $X \in \cM_{d_A}$. Any representation of this form is called a \emph{Kraus representation} of the channel $\cT$ and the operators $\cbr{K_i}_{i\in I}$ are called the corresponding \emph{Kraus operators}. A quantum channel is called \emph{unitary} if it admits a Kraus decomposition with a single unitary Kraus operator, and it is called \emph{entanglement breaking} if it admits a Kraus representation with Kraus operators $K_i$ of rank $1$. Consider quantum systems labelled $A_1,A_2,B_1$ and $B_2$. A bipartite quantum channel $\cT:\cM_{d_{A_1}}\otimes \cM_{d_{B_1}}\ra \cM_{d_{A_2}}\otimes \cM_{d_{B_2}}$ is called a \emph{separable quantum channel} with respect to the bipartition $(A_1,A_2):(B_1,B_2)$ if it admits a Kraus representation with Kraus operators of the form $K_i = K^{A}_i\otimes K^{B}_i$ with operators $K^{A}_i:\C^{d_{A_1}}\ra \C^{d_{A_2}}$ and $K^{B}_i:\C^{d_{B_1}}\ra \C^{d_{B_2}}$. We denote the set of these quantum channels by $\mathrm{SepC}\br{(A_1,A_2):(B_1,B_2)}$. The set of quantum channels from $\cM_{d_A}$ to $\cM_{d_B}$ is compact and convex, and its extreme points are given by the quantum channels $\cT:\cM_{d_A}\rightarrow\cM_{d_B}$ having a Kraus representation $\cT\br{X}=\sum_i K_i X K_i^{\dagger}$ such that $\cbr{K_i^\dagger K_j}_{i,j}$ is a linearly independent set~\cite{Choi}. For any quantum channel $\cT:\cM_{d_A}\rightarrow\cM_{d_B}$, there exists an isometry $V:\C^{d_A} \rightarrow \C^{d_B}\otimes \C^{d_E}$, for some $d_E\in \N$, such that $\cT(X)=\Tr_E\br{VXV^\dagger}$, for every $X\in\C^{d_A}$. Any such representation of $\cT$ is called a \emph{Stinespring representation} and the isometry $V$ is referred to as a \emph{Stinespring dilation} of $\cT$. 

\textbf{Trace-distance, quantum $\chi^2$-divergence, and contraction coefficients.} We will need the \emph{trace-norm contraction coefficient} of a quantum channel $\cT:\cM_d\rightarrow\cM_d$ given by 
\begin{equation}\label{equ:QDobrushin}
    \eta_{\text{tr}}\br{\cT} := \sup_{\rho,\sigma} \frac{\onenorm{\cT(\rho)-\cT(\sigma)}}{\onenorm{\rho-\sigma}
    } \enspace,    
\end{equation}
where the supremum is over all pairs of quantum states. We will often use that 
\begin{equation}\label{equ:TNContract}
    \eta_{\text{tr}}\br{\cT} = \frac{1}{2}\max_{\psi\perp\phi}\onenorm{ \cT\br{\proj{\psi}{\psi}-\proj{\phi}{\phi}}} \enspace,
\end{equation}
where the maximum is over orthogonal pairs of pure states (see~\cite{ruskai1994beyond}).

For a pair of density operators $\rho$ and $\sigma$, the $\chi^2$-divergence is defined by 
\begin{align*}
\chi^2(\rho, \sigma) &\coloneqq \Tr\left((\rho - \sigma) \sigma^{-1/2} (\rho - \sigma) \sigma^{-1/2}) \right) \ ,
\end{align*}
when $\mathrm{supp}(\rho) \subseteq \mathrm{supp}(\sigma)$ and $+\infty$, otherwise. The operator $\sigma^{-1/2}$ is to be understood as generalized inverse of $\sigma^{1/2}$. Note that we have $\chi^2(\rho, \sigma) = \Tr(\rho \sigma^{-1/2} \rho \sigma^{-1/2}) - 1$. 

We will use the \emph{$\chi^2$ contraction coefficient} of a quantum channel $\cT:\cM_d\rightarrow\cM_d$ given by
\begin{align}
\eta_{\chi}\br{\cT} &\coloneqq \sup_{\rho, \sigma} \frac{\chi^2(\cT(\rho), \cT(\sigma))}{\chi^2(\rho, \sigma)}\enspace,
\end{align}
where the supremum is over all pairs of quantum states. For any quantum channel $\cT:\cM_d\rightarrow\cM_d$, the following inequality holds~\cite[Theorem 14]{TKRWV10}:
\begin{equation} \label{eq:eta_chi vs eta_tr}
    \eta_{\chi}\br{\cT} \leq \eta_{\mathrm{tr}}\br{\cT}\enspace.
\end{equation}

\textbf{Representation of qubit channels.} 
\begin{lemma}\label{lem:UnitalCaseLemma}
Any unital qubit channel $\cN:\cM_2\ra \cM_2$ can be written as a convex combination
\[
\cN = (1-p)\cT + p\cB,
\]
where $\cT:\cM_2\ra\cM_2$ is a unitary quantum channel and $\cB:\cM_2\ra\cM_2$ is entanglement breaking. 
\end{lemma}

\section{Maximal length of noisy quantum computation} \label{sec:exp bnd}

Let $C$ be a quantum circuit of width $n$ and length $T$ defined by a sequence of quantum channels $\cbr{\cL_i}_{i\in[T]}$. For $i\in\{0,\ldots,T\}$, let $(A_i:B_i)$ be a bipartition of the registers of the circuit after $i$ time steps into disjoint subsets such that $\cL_i\in \mathrm{SepC}\br{A_{i-1},A_{i}:B_{i-1},B_i}$, i.e., $\cL_i$ in each time step is a separable channel with respect to the bipartition of the subsystems into the $A$ and $B$ parts. Furthermore, for every $i\in\cbr{0,\ldots,T}$, let $A_i=A^c_iA^q_i$ and $B_i=B^c_iB^q_i$, where $A^c_i$ and $B^c_i$ are classical subsystems of $A_i$ and $B_i$, respectively, of arbitrary finite dimensions and $A^q_i$ and $B^q_i$ are the quantum subsystems which contain a total of $n_i$ qubits. Let $\cN$ be an arbitrary non-unitary qubit channel.

We define
\begin{align*}
\chisep{A:B}\br{\tau_{AB}} &= \min_{\sigma \in \mathrm{Sep}\br{A:B}} \chi^2(\tau_{AB}, \sigma_{AB}) \ .
\end{align*}
It is simple to see that this measure is monotone under separable quantum channels and convex in the state.

We denote by $\rho_{AB}^i$ the state of the noisy circuit after $i$ time steps.

\begin{lemma} \label{lem:expr_chisep}
    Let $\rho_{XYAB}$ be a cc-qq state of the form $\rho_{XYAB} = \sum_{x,y} p_{xy} \proj{x}{x}_{X} \otimes \proj{y}{y}_{Y} \otimes \rho_{AB}^{xy}$. Then, we have
    \begin{align}
    \label{eq:bound_chi2_sep}
        \chisep{XA:BY}(\rho_{XYAB}) \leq d_{A} d_{B} - 1 \ .
    \end{align}
    In addition, we can express the $\chi^2$ divergence to separable states $\mathrm{Sep}\br{XA:BY}$ as
    \begin{align}
    \label{eq:expr_chi2_sep}
        \chisep{XA:BY}(\rho_{XYAB}) =  \left(\sum_{x,y} p_{xy} \sqrt{\chisep{A:B}(\rho^{xy}_{AB}) + 1} \right)^2 - 1 \ .
    \end{align}
\end{lemma}
```


