ground_truth_solution:
We start by proving the following auxiliary statement:

\begin{lemma}\label{lem:Chi2ContractionFromEta}
Let $\rho_{X Y A_1 B_1}$ be a cc-qq state of the form given in Lemma~\ref{lem:expr_chisep}. Then, for any separable quantum channel $\cT\in \mathrm{SepC}\br{(A_1,A_2):(B_1,B_2)}$, we have
\[
\chisep{XA_2:B_2Y}((\cI_{XY}\otimes \cT)(\rho_{XYA_1B_1})) \leq \sqrt{\eta_{\chi}(\cT)}\chisep{XA_1:B_1Y}(\rho_{XYA_1B_1}).
\]
\end{lemma}
\begin{proof}
By Lemma \ref{lem:expr_chisep} we have
\begin{align*}
\chisep{XA_2:B_2Y}((\cI_{XY}\otimes \cT)(\rho_{XYA_1B_1})) &= \left(\sum_{x,y}p_{xy}\sqrt{\chisep{A_2:B_2}(\cT(\rho^{xy}_{A_1B_1}))+1}\right)^2 - 1 \\
&\leq \left(\sum_{x,y}p_{xy}\sqrt{\eta_{\chi}(\cT)\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}\right)^2 - 1
\end{align*}
The final expression can be written as
\begin{align*}
&\lb\lbr \sum_{x,y}p_{xy}\sqrt{\eta_{\chi}(\cT)\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}\rbr - 1\rb\lb\lbr\sum_{x,y}p_{xy}\sqrt{\eta_{\chi}(\cT)\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}\rbr + 1\rb \\
&=\lb \sum_{x,y}p_{xy}\lbr\sqrt{\eta_{\chi}(\cT)\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}-1\rbr\rb\lb\sum_{x,y}p_{xy}\lbr\sqrt{\eta_{\chi}(\cT)\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}+1\rbr\rb \\
&\leq \sqrt{\eta_{\chi}(\cT)}\lb\sum_{x,y}p_{xy}\lbr\sqrt{\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}-1\rbr\rb\lb\sum_{x,y}p_{xy}\lbr\sqrt{\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}+1\rbr\rb \\
&=\sqrt{\eta_{\chi}(\cT)} \lb\lb\sum_{x,y}p_{xy}\sqrt{\chisep{A_1:B_1}(\rho^{xy}_{A_1B_1})+1}\rb^2 - 1\rb \\
&=\sqrt{\eta_{\chi}(\cT)}\chisep{XA_1:B_1Y}(\rho_{XYA_1B_1}),
\end{align*}
where we used that $\eta_{\chi}(\cT)\leq 1$ and the elementary inequality $\sqrt{at+1}-1\leq \sqrt{a}\lb \sqrt{t+1}-1\rb$, which is valid for $a\in \left[ 0,1\right]$ and any $t\geq 0$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
    In time step $i+1$, each of the $n_{i}$ qubits in the noisy circuit goes through the noise channel $\cN:\cM_2 \rightarrow \cM_2$ followed by a separable channel $\cL_{i+1}\in \mathrm{SepC}\br{A_{i},A_{i+1}:B_{i},B_{i+1}}$. We use two different approaches to prove Lemma~\ref{lem:chiSEPcontraction} for unital and non-unital quantum channels. 

    \textbf{Case I: $\cN$ is unital.} In this case, we prove the contractivity of $\chisep{A:B}$ independent of the initial value $\chisep{A:B}\br{\rho^{i}}$. By Lemma \ref{lem:UnitalCaseLemma}, we may write 
    \begin{equation}
        \cN= \br{1-p} \, \cT + p \, \cB \enspace,
    \end{equation}
    where $\cT:\cM_2\ra\cM_2$ is a unitary quantum channel and $\cB:\cM_2\ra \cM_2$ is entanglement breaking. Since $\cN$ itself is not unitary, we have $p>0$. There exists a separable quantum channel $\cS:\cM_{2^{n_{i}}} \rightarrow \cM_{2^{n_{i}}}$ with respect to the bipartition into $A$ and $B$, such that 
    \begin{equation}
        \cN^{\otimes n_{i}} = \br{1-p^{n_{i}}} \cS + p^{n_{i}}\, \cB^{\otimes n_i}\enspace,
    \end{equation}
    and we can compute
    \begin{align}
       \chisep{A:B}\br{\rho^{i+1}} &= \chisep{A:B}\br{\br{\cL_{i+1} \circ \br{\cN^{\otimes n_{i}} \otimes \cI^{A^c_iB^c_i}} }\br{\rho^{i}}} \\
       &\leq \chisep{A:B}\br{\br{\cN^{\otimes n_{i}} \otimes \cI^{A^c_iB^c_i}}\br{\rho^i}}\\
       &\leq \br{1-p^{n_{i}}} \chisep{A:B}\br{\br{\cS\otimes \cI^{A^c_iB^c_i}}\br{\rho^i}} \\
       &\hspace{1.4em} + p^{n_{i}}\, \chisep{A:B}\br{\br{\cB^{\otimes n_{i}}\otimes \cI^{A^c_iB^c_i}}\br{\rho^i}}\\
       &= \br{1-p^{n_i}} \chisep{A:B}\br{\br{\cS\otimes \cI^{A^c_iB^c_i}}\br{\rho^i}} \\
       &\leq \br{1-p^{n}} \chisep{A:B}\br{\rho^i}\enspace.
    \end{align}
    Here, the first and the last inequalities follow from monotonicity of $\chisep{A:B}$ under separable quantum channels, and the second inequality follows from convexity of $\chisep{A:B}$. Moreover, the second equality holds since $\cB$ is entanglement breaking and $\rho^i$ is classical on $A^c_iB^c_i$. 

    \textbf{Case II: $\cN$ is non-unital.} By Lemma~\ref{lem:Chi2ContractionFromEta} in the appendix for $\cT=\cN^{\otimes n_i}$ we have 
    \begin{equation} \label{eq:chisep_contraction}
        \chisep{A:B}\br{\br{\cN^{\otimes n_{i}} \otimes \cI^{A^c_iB^c_i}}\br{\rho^i}} \leq \sqrt{\eta_\chi\br{\cN^{\otimes n_i}}} \chisep{A:B} \br{\rho^i}\enspace.
    \end{equation}
    By Eq.~\eqref{eq:eta_chi vs eta_tr}, we have $\eta_\chi\br{\cN^{\otimes n_i}}\leq \eta_\mathrm{tr}\br{\cN^{\otimes n_i}}$. So we focus on bounding $\eta_\mathrm{tr}\br{\cN^{\otimes n_i}}$. The definition \eqref{equ:QDobrushin} of the trace-norm contraction coefficient might not be easily computable for all channels, and it is unclear how it behaves under tensor powers. In order to prove the lemma we prove a general upper bound on the trace-norm contraction coefficient of a quantum channel.

    \begin{lemma} \label{lem:UB on Dobrushin}
        For any quantum channel $\cT:\cM_d \rightarrow \cM_d$, we have
        \begin{equation}
            \eta_{\mathrm{tr}}(\cT)\leq \sqrt{1-\frac{\lambda^{\mathrm{out}}_{\min}\br{\cT^\dagger \circ \cT}}{d^2}}\enspace.
        \end{equation}
   Here, we used the minimal output eigenvalue $\lambda^{\mathrm{out}}_{\min} \br{\cT^\dagger \circ \cT} = \displaystyle{\min_{\psi,\phi}} \,\bra{\psi}(\cT^\dagger \circ \cT)(\proj{\phi}{\phi})\ket{\psi}$, where the minimum goes over pure quantum states.
    \label{lem:EtaBoundMinOutEV}
    \end{lemma}

    \begin{proof}
        In \cite{watrous2009semidefinite} the fidelity $\mathrm{F}(\rho,\sigma)=\|\sqrt{\rho}\sqrt{\sigma}\|^2_1$ of quantum states $\rho$ and $\sigma$ on $\C^d$ is expressed as a semidefinite program 
        \begin{equation}
            \mathrm{F}(\rho,\sigma) = \max\cbr{ \bra{v} W\ket{v} ~:~ W_{AE}\geq 0, \Tr_E\br{W_{AE}} \leq \rho },
        \end{equation}
        where $v\in \C^{d}\otimes \C^{d_E}$ is a purification of $\sigma$. Consider the case $\rho=\cT(\proj{\psi}{\psi})$ and $\sigma=\cT(\proj{\phi}{\phi})$ for pure states $\ket{\psi},\ket{\phi}\in\C^d$. Let $V:\C^{d}\rightarrow \C^{d}\otimes \C^{d_E}$ denote a Stinespring dilation of $\cT$ such that 
        \begin{equation}
            \cT(X) = \Tr_E\br{VXV^{\dagger}}\enspace.
        \end{equation}
        Note that $V\ket{\phi}\in \C^{d}\otimes \C^{d_E}$ is a purification of $\sigma$. Choosing $W=\cT(\proj{\psi}{\psi})\otimes \frac{\id_E}{d_E}$ we find that 
        \begin{equation}
             \mathrm{F}(\rho,\sigma)\geq \bra{\phi}V^\dagger \br{ \cT(\proj{\psi}{\psi})\otimes \frac{\id_E}{d_E}} V\ket{\phi} = \frac{1}{d_E}\bra{\phi}\cT^\dagger \circ \cT\br{\proj{\psi}{\psi}} \ket{\phi}\enspace,
        \end{equation}
        where we used that the adjoint of $\cT$ has the Stinespring dilation
        \begin{equation}
            \cT^\dagger(X) = V^\dagger (X\otimes \id_E) V\enspace.
        \end{equation}
        Finally, we can apply the well-known Fuchs-van-de-Graaf inequality relating the trace norm and the fidelity ($\| \rho - \sigma \|_1 \leq \sqrt{1-\mathrm{F}(\rho, \sigma)}$ for any quantum states $\rho, \sigma$) to conclude
        \begin{align*}
            \eta_{\text{tr}}(\cT) &= \frac{1}{2}\max_{\psi\perp\phi}\| \cT(\proj{\psi}{\psi}-\proj{\phi}{\phi})\|_1 \\
            &\leq \max_{\psi\perp\phi} \sqrt{1-\mathrm{F}(\cT(\proj{\psi}{\psi}),\cT(\proj{\phi}{\phi}))} \\
            &\leq \max_{\psi\perp\phi}\sqrt{1-\frac{1}{d^2}\bra{\phi}\br{\cT^\dagger \circ \cT} \br{\proj{\psi}{\psi}} \ket{\phi}} \\
            & \leq  \sqrt{1-\frac{\lambda^{\mathrm{out}}_{\min}\br{ \cT^\dagger\circ \cT}}{d^2}}\enspace,
        \end{align*}
        where we used that $d_E\leq d^2$ for any quantum channel $\cT:\cM_d \rightarrow \cM_d$.
    \end{proof}

Computing $\lambda^{\mathrm{out}}_{\min}\br{\cT^\dagger \circ \cT}$ might be difficult in general, but for our purposes an easy lower bound suffices. This bound also behaves nicely under tensor product of channels; an important property which we use below. For $\ket{\phi}=\sum_{i\in[d]} \alpha_i \ket{i}$, let $\ket{\overline{\phi}}=\sum_{i\in[d]} \overline{\alpha_i} \ket{i}$, where $\overline{\alpha_i}$ denotes the complex conjugate of $\alpha_i$. Then we have
\begin{equation}
\lambda^{\mathrm{out}}_{\min} \br{\cT^\dagger\circ \cT} = \min_{\psi,\phi} \,\bra{\psi}(\cT^\dagger \circ \cT)(\proj{\phi}{\phi})\ket{\psi}=\min_{\psi,\phi}\, \bra{\psi\otimes \overline{\phi}}C_{\cT^\dagger\circ \cT} \ket{\psi\otimes \overline{\phi}} \geq \lambda_{\min} \br{C_{\cT^\dagger\circ \cT}}.
\label{eq:EasyBound}
\end{equation}


  We are now in position to present the proof of the case where $\cN$ is a non-unital qubit channel. We may write 
    \begin{equation}
        \cN= (1-q)\,\cM' + q \, \cM ,
    \end{equation}
  where $q\in(0,1]$ and $\cM$ is a non-unital extreme point of the set of qubit channels. By the characterization of extreme points of the set of quantum channels (see preliminaries or \cite{Choi}), the non-unital extremal qubit channel $\cM$ admits a Kraus decomposition with two Kraus operators $K_1,K_2:\C^2\ra \C^2$ such that the operators $K_1^\dagger K_1,K_1^\dagger K_2,K_2^\dagger K_1,K_2^\dagger K_2$ are linearly independent. Since these operators are exactly the Kraus operators of the completely positive map $\cM^\dagger \circ \cM$, we conclude that the Choi matrix $C_{\cM^\dagger \circ \cM}$ is full-rank and that
\[
\lambda_{\min} \br{C_{\cN^\dagger \circ \cN}} \geq q^2\lambda_{\min} \br{C_{\cM^\dagger \circ \cM}}>0 .
\]  

Setting $\cT=\cN^{\otimes n_i}$ and using~\eqref{eq:EasyBound} and Lemma~\ref{lem:EtaBoundMinOutEV}, we have 
    \begin{align}
        \eta_{\text{tr}}(\cT) &\leq \sqrt{1-\frac{\lambda_{\min}\br{C_{\cT^\dagger \circ \cT}}}{2^{2n_i}}} \!=\!
        \sqrt{1-\frac{\lambda_{\min}\br{\br{C_{\cN^\dagger \circ \cN}}^{\otimes n_i}}}{2^{2n_i}}} \!=\! \sqrt{1-\br{\frac{\lambda_{\min}\br{C_{\cN^\dagger \circ \cN}}}{4}}^{n_i}} \nonumber\\
        &\leq \sqrt{1-\br{\frac{q^2\lambda_{\min}\br{C_{\cM^\dagger \circ \cM}}}{4}}^{n_i}} \leq 1-\br{\frac{q^2\lambda_{\min}\br{C_{\cM^\dagger \circ \cM}}}{8}}^{n_i}\enspace. \label{eq:ubd_on_eta_tr}
    \end{align}
    Combining Eqs.~\eqref{eq:chisep_contraction} and~\eqref{eq:ubd_on_eta_tr}, for $p=\br{q^2/16}\lambda_{\min}\br{C_{\cM^\dagger \otimes \cM}}>0$, we have 
    \begin{align*}
        \chisep{A:B}\br{\rho^{i+1}} &= \chisep{A:B}\br{\br{\cL_{i+1} \circ \br{\cN^{\otimes n_{i}} \otimes \cI^{A^c_iB^c_i}} }\br{\rho^{i}}}\\ 
        &\leq \chisep{A:B}\br{\br{\cN^{\otimes n_{i}} \otimes \cI^{A^c_iB^c_i}}\br{\rho^i}}\\
        &\leq \br{1-p^{n_i}} \chisep{A:B}\br{\rho^i} \leq \br{1-p^{n}} \chisep{A:B}\br{\rho^i}\enspace.
    \end{align*}
\end{proof}
